// Writes app/cases.generated.ts from workloads.mjs (see there). `--check` fails if the committed
// file differs. Usage: node benchmarks/turbo-compare/gen-cases.mjs [--check]
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { WORKLOADS } from './workloads.mjs';

const OUT = path.join(path.dirname(fileURLToPath(import.meta.url)), 'app/cases.generated.ts');

export function render() {
  const lines = [
    '// @generated by benchmarks/turbo-compare/gen-cases.mjs from workloads.mjs; do not edit.',
    '// One literal loop per (workload, path): each path has its own call site.',
    "import type { Case, Fixtures, Receivers } from './types';",
    '',
    'export function makeCases(r: Receivers, fx: Fixtures): Case[] {',
    '  return [',
  ];
  for (const w of WORKLOADS) {
    for (const [pathId, p] of Object.entries(w.paths)) {
      const body = p.body.replaceAll('$M', 'M');
      lines.push(
        '    {',
        `      workload: '${w.id}',`,
        `      path: '${pathId}',`,
        `      expect: (n: number) => ${w.expect},`,
        '      run: ((M) => (n: number): number => {',
        ...(w.pre ? [`        ${w.pre}`] : []),
        ...(/\bacc\b/.test(p.body + w.ret) ? ['        let acc = 0;'] : []),
        '        for (let i = 0; i < n; i++) {',
        `          ${body}`,
        '        }',
        `        return ${w.ret};`,
        `      })(r.${p.receiver}),`,
        '    },',
      );
    }
  }
  lines.push('  ];', '}', '');
  return lines.join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const text = render();
  if (process.argv.includes('--check')) {
    if (readFileSync(OUT, 'utf8') !== text) {
      console.error(`${OUT} is stale: run node benchmarks/turbo-compare/gen-cases.mjs`);
      process.exit(1);
    }
  } else writeFileSync(OUT, text);
}
